let count = 0;
for (const [slug, data] of Object.entries(richData2)) {
  const file = path.join(DEST_DIR, `${slug}.json`);
  if (fs.existsSync(file)) {
    const d = JSON.parse(fs.readFileSync(file, 'utf8'));
    d.topPlaces = data.topPlaces;
    d.hotels = data.hotels;
    fs.writeFileSync(file, JSON.stringify(d, null, 2), 'utf8');
    count++;
    console.log(`Enriched ${slug} with ${data.topPlaces.length} places and ${data.hotels.length} stays.`);
  }
}

console.log(`Successfully enriched ${count} additional destination files with 6 places & 4 stays each!`);
